TradingStrategy::TradingStrategy(int smaPeriod, double stopLossMultiplier, double riskPercentage)
    : smaPeriod(smaPeriod), stopLossMultiplier(stopLossMultiplier), riskPercentage(riskPercentage) {
    if (stopLossMultiplier <= 0 || riskPercentage <= 0 || riskPercentage > 100) {
        throw std::invalid_argument("Invalid stopLossMultiplier or riskPercentage");
    }
}

std::vector<Signal> TradingStrategy::calculateSignals(const std::vector<double>& priceData) {
    if (priceData.size() < static_cast<size_t>(smaPeriod)) {
        throw std::runtime_error("Insufficient data for SMA calculation");
    }

    std::vector<double> sma = TechnicalIndicators::calculateSMA(priceData, smaPeriod);
    std::vector<double> atr = calculateATR(priceData, 14);  // 14-period ATR
    std::vector<Signal> signals;

    for (size_t i = smaPeriod; i < priceData.size(); ++i) {
        Signal signal;
        signal.time = i;
        signal.price = priceData[i];

        if (priceData[i] > sma[i - smaPeriod] && priceData[i - 1] <= sma[i - smaPeriod - 1]) {
            signal.type = SignalType::BUY;
            signal.stopLoss = priceData[i] - stopLossMultiplier * atr[i];
        } else if (priceData[i] < sma[i - smaPeriod] && priceData[i - 1] >= sma[i - smaPeriod - 1]) {
            signal.type = SignalType::SELL;
            signal.stopLoss = priceData[i] + stopLossMultiplier * atr[i];
        } else {
            signal.type = SignalType::NONE;
        }

        if (signal.type != SignalType::NONE) {
            signal.positionSize = calculatePositionSize(signal.price, signal.stopLoss);
            signals.push_back(signal);
        }
    }

    return signals;
}

std::vector<double> TradingStrategy::calculateATR(const std::vector<double>& priceData, int period) {
    std::vector<double> trueRanges;
    for (size_t i = 1; i < priceData.size(); ++i) {
        double highLow = std::abs(priceData[i] - priceData[i-1]);
        trueRanges.push_back(highLow);
    }

    return TechnicalIndicators::calculateSMA(trueRanges, period);
}

double TradingStrategy::calculatePositionSize(double currentPrice, double stopLoss) const {
    double riskAmount = accountBalance * (riskPercentage / 100.0);
    double riskPerShare = std::abs(currentPrice - stopLoss);
    return std::floor(riskAmount / riskPerShare);
}

void TradingStrategy::setAccountBalance(double balance) {
    if (balance <= 0) {
        throw std::invalid_argument("Account balance must be positive");
    }
    accountBalance = balance;
}

void TradingStrategy::backtest(const std::vector<double>& priceData) {
    std::vector<Signal> signals = calculateSignals(priceData);
    double totalProfit = 0.0;
    int winningTrades = 0;
    int losingTrades = 0;

    for (size_t i = 0; i < signals.size() - 1; ++i) {
        double entryPrice = signals[i].price;
        double exitPrice = signals[i + 1].price;
        double profit = (signals[i].type == SignalType::BUY) ? 
                        (exitPrice - entryPrice) * signals[i].positionSize :
                        (entryPrice - exitPrice) * signals[i].positionSize;

        totalProfit += profit;
        if (profit > 0) ++winningTrades;
        else ++losingTrades;

        // Log trade details
        std::cout << "Trade " << i + 1 << ": " 
                  << (signals[i].type == SignalType::BUY ? "BUY" : "SELL")
                  << " Entry: " << entryPrice
                  << " Exit: " << exitPrice
                  << " Profit: " << profit << std::endl;
    }

    std::cout << "Total Profit: " << totalProfit << std::endl;
    std::cout << "Win Rate: " << (static_cast<double>(winningTrades) / (winningTrades + losingTrades)) * 100 << "%" << std::endl;
}
